+	 * beneficial for this listener). Never invoked if no listener ever attaches or if the buffer is empty.
 	 *
 	 * @example
 	 * ```
@@ -512,7 +516,7 @@ export namespace Event {
 	 * this.onInstallExtension = Event.buffer(service.onInstallExtension, 'onInstallExtension', true);
 	 * ```
 	 */
-	export function buffer<T>(event: Event<T>, debugName: string, flushAfterTimeout = false, _buffer: T[] = [], disposable?: DisposableStore): Event<T> {
+	export function buffer<T>(event: Event<T>, debugName: string, flushAfterTimeout = false, _buffer: T[] = [], disposable?: DisposableStore, reportBufferedOnFirstListener?: (bufferedCount: number) => void): Event<T> {
 		let buffer: T[] | null = _buffer.slice();

 		// Dev-only leak detection: track when buffer was created and warn
@@ -576,6 +580,9 @@ export namespace Event {

 			onDidAddFirstListener() {
 				if (buffer) {
+					if (buffer.length > 0) {
+						reportBufferedOnFirstListener?.(buffer.length);
+					}
 					if (flushAfterTimeout) {
 						setTimeout(flush);
 					} else {
diff --git a/src/vs/base/parts/ipc/common/ipc.ts b/src/vs/base/parts/ipc/common/ipc.ts
index c767d36a7976a..93b6e7a3b3e6d 100644
--- a/src/vs/base/parts/ipc/common/ipc.ts
+++ b/src/vs/base/parts/ipc/common/ipc.ts
@@ -1141,9 +1141,24 @@ export namespace ProxyChannel {

 	export interface ICreateServiceChannelOptions extends IProxyOptions { }

+	let bufferUsageReporter: ((serviceName: string, eventName: string, bufferedCount: number) => void) | undefined;
+
+	/**
+	 * Sets a process-wide reporter invoked when a {@link fromService} channel flushes buffered events to a
+	 * late-attaching listener, to discover which channels rely on buffering. Pass `undefined` to clear.
+	 */
+	export function setBufferUsageReporter(reporter: ((serviceName: string, eventName: string, bufferedCount: number) => void) | undefined): void {
+		bufferUsageReporter = reporter;
+	}
+
 	export function fromService<TContext>(service: unknown, disposables: DisposableStore, options?: ICreateServiceChannelOptions): IServerChannel<TContext> {
 		const handler = service as { [key: string]: unknown };
 		const disableMarshalling = options?.disableMarshalling;
+		const serviceName = (service as { constructor?: { name?: string } })?.constructor?.name ?? 'unknownService';
+
+		const reportBufferUsage = (eventName: string, bufferedCount: number): void => {
+			bufferUsageReporter?.(serviceName, eventName, bufferedCount);
+		};

 		// Buffer any event that should be supported by
 		// iterating over all property keys and finding them
@@ -1153,7 +1168,7 @@ export namespace ProxyChannel {
 		const mapEventNameToEvent = new Map<string, Event<unknown>>();
 		for (const key in handler) {
 			if (propertyIsEvent(key)) {
-				mapEventNameToEvent.set(key, Event.buffer(handler[key] as Event<unknown>, key, true, undefined, disposables));
+				mapEventNameToEvent.set(key, Event.buffer(handler[key] as Event<unknown>, key, true, undefined, disposables, count => reportBufferUsage(key, count)));
 			}
 		}

@@ -1172,7 +1187,7 @@ export namespace ProxyChannel {
 					}

 					if (propertyIsEvent(event)) {
-						mapEventNameToEvent.set(event, Event.buffer(handler[event] as Event<unknown>, event, true, undefined, disposables));
+						mapEventNameToEvent.set(event, Event.buffer(handler[event] as Event<unknown>, event, true, undefined, disposables, count => reportBufferUsage(event, count)));

 						return mapEventNameToEvent.get(event) as Event<T>;
 					}
diff --git a/src/vs/base/test/common/event.test.ts b/src/vs/base/test/common/event.test.ts
index cf3c252b90902..b8880477b2c11 100644
--- a/src/vs/base/test/common/event.test.ts
+++ b/src/vs/base/test/common/event.test.ts
@@ -1060,6 +1060,32 @@ suite('Event utils', () => {
 			ds.add(bufferedEvent(num => result.push(num)));
 			assert.deepStrictEqual(result, [-2, -1, 0, 1, 2, 3]);
 		});
+
+		test('should report buffered count when first listener attaches with buffered events', () => {
+			const reported: number[] = [];
+			const emitter = ds.add(new Emitter<number>());
+			const bufferedEvent = Event.buffer(emitter.event, 'test', false, undefined, undefined, count => reported.push(count));
+
+			emitter.fire(1);
+			emitter.fire(2);
+			emitter.fire(3);
+			assert.deepStrictEqual(reported, [] as number[]);
+
+			ds.add(bufferedEvent(() => { }));
+			assert.deepStrictEqual(reported, [3]);
+		});
+
+		test('should not report when first listener attaches with empty buffer', () => {
+			const reported: number[] = [];
+			const emitter = ds.add(new Emitter<number>());
+			const bufferedEvent = Event.buffer(emitter.event, 'test', false, undefined, undefined, count => reported.push(count));
+
+			ds.add(bufferedEvent(() => { }));
+			assert.deepStrictEqual(reported, [] as number[]);
+
+			emitter.fire(1);
+			assert.deepStrictEqual(reported, [] as number[]);
+		});
 	});

 	suite('EventMultiplexer', () => {
